<?php
 namespace QQWorld\Braintree\Gateway\Request; use QQWorld\Payment\Gateway\Request\BuilderInterface; use QQWorld\Braintree\Gateway\Helper\SubjectReader; class AddressDataBuilder implements BuilderInterface { const SHIPPING_ADDRESS = 'shipping'; const BILLING_ADDRESS = 'billing'; const FIRST_NAME = 'firstName'; const LAST_NAME = 'lastName'; const COMPANY = 'company'; const STREET_ADDRESS = 'streetAddress'; const EXTENDED_ADDRESS = 'extendedAddress'; const LOCALITY = 'locality'; const REGION = 'region'; const POSTAL_CODE = 'postalCode'; const COUNTRY_CODE = 'countryCodeAlpha2'; private $subjectReader; public function __construct(SubjectReader $subjectReader) { $this->subjectReader = $subjectReader; } public function build(array $buildSubject) { $paymentDO = $this->subjectReader->readPayment($buildSubject); $order = $paymentDO->getOrder(); $result = []; $billingAddress = $order->getBillingAddress(); if ($billingAddress) { $result[self::BILLING_ADDRESS] = [ self::FIRST_NAME => $billingAddress->getFirstname(), self::LAST_NAME => $billingAddress->getLastname(), self::COMPANY => $billingAddress->getCompany(), self::STREET_ADDRESS => $billingAddress->getStreetLine1(), self::EXTENDED_ADDRESS => $billingAddress->getStreetLine2(), self::LOCALITY => $billingAddress->getCity(), self::REGION => $billingAddress->getRegionCode(), self::POSTAL_CODE => $billingAddress->getPostcode(), self::COUNTRY_CODE => $billingAddress->getCountryId() ]; } $shippingAddress = $order->getShippingAddress(); if ($shippingAddress) { $result[self::SHIPPING_ADDRESS] = [ self::FIRST_NAME => $shippingAddress->getFirstname(), self::LAST_NAME => $shippingAddress->getLastname(), self::COMPANY => $shippingAddress->getCompany(), self::STREET_ADDRESS => $shippingAddress->getStreetLine1(), self::EXTENDED_ADDRESS => $shippingAddress->getStreetLine2(), self::LOCALITY => $shippingAddress->getCity(), self::REGION => $shippingAddress->getRegionCode(), self::POSTAL_CODE => $shippingAddress->getPostcode(), self::COUNTRY_CODE => $shippingAddress->getCountryId() ]; } return $result; } } 